<script lang="ts">import type {HrSample} from '../generated/HrSample';import {colors} from '../charts';let {samples,floors}:{samples:HrSample[],floors:number[]}=$props();let maxT=$derived(Math.max(1,...samples.map(s=>s.tS))),lo=$derived(Math.min(100,...samples.map(s=>s.bpm))-5),hi=$derived(Math.max(180,...samples.map(s=>s.bpm))+5),y=(v:number)=>116-(v-lo)/(hi-lo)*110;let d=$derived(samples.map((s,i)=>`${i?'L':'M'}${(s.tS/maxT*326).toFixed(1)},${y(s.bpm).toFixed(1)}`).join(''));let stops=$derived([...floors].reverse());</script><svg class="chart" viewBox="0 0 326 132" aria-label="Heart rate during workout"><defs><linearGradient id="hr-zones" x1="0" y1="0" x2="0" y2="132" gradientUnits="userSpaceOnUse">{#each stops as floor,i}{@const offset=Math.max(0,Math.min(1,y(floor)/132))}<stop {offset} stop-color={colors.z[4-i]}/><stop {offset} stop-color={colors.z[3-i]}/>{/each}</linearGradient><linearGradient id="hr-area" x1="0" y1="0" x2="0" y2="1"><stop stop-color={colors.amber} stop-opacity=".28"/><stop offset="1" stop-color={colors.amber} stop-opacity="0"/></linearGradient></defs>{#each floors as f}<line x1="0" x2="326" y1={y(f)} y2={y(f)} stroke="rgba(255,255,255,.06)" stroke-dasharray="3 4"/>{/each}{#if d}<path d={`${d}L326,116L0,116Z`} fill="url(#hr-area)"/><path {d} fill="none" stroke="url(#hr-zones)" stroke-width="2.2" stroke-linejoin="round"/>{/if}{#each [0,15,30,45] as t,i}<text x={i*85+2} y="130" fill="#69728A" font-size="11">{t}{i===3?' min':''}</text>{/each}</svg><style>.chart{width:100%;display:block}</style>